import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.99, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withServer(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try { return await fn(`http://localhost:${server.address().port}`) } finally { server.close() }
}

async function totalFor(items) {
  return withServer(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    return (await res.json()).total
  })
}

// Characterization tests: pin the CURRENT behavior of order totals.
test('no discount below threshold', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 5 }]), 50)
})
test('no discount at exactly 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})
test('10% discount just above 100 (101 -> 90.9 -> 90)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }, { sku: 'C', qty: 1 }, { sku: 'C', qty: 1 }].slice(0, 1).concat([{ sku: 'A', qty: 0 }]).concat([{ sku: 'D', qty: 0 }])), 100)
  assert.equal(await totalFor([{ sku: 'B', qty: 4 }, { sku: 'C', qty: 1 }]), 91) // 102.99 -> 92.691 -> 92
})
test('large order discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900)
  assert.equal(await totalFor([{ sku: 'A', qty: 1000 }]), 9000)
})
test('fractional totals are floored to whole euros (cents dropped)', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 7 }]), 209) // 233.31 * 0.9 = 209.979
  assert.equal(await totalFor([{ sku: 'C', qty: 3 }]), 2) // 2.97, no discount
})
test('multiple line items are summed before discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 6 }, { sku: 'B', qty: 2 }]), 100) // 111 -> 99.9 -> 99
})
EOF
